    @Test
    public void shellCommandWithTimeoutRunsInShellUnderTimeout() {
        givenCommand("exit 3", true, 5);

        whenExecutedUnprivileged();

        thenSuRuns("timeout -s SIGTERM 5 /bin/sh -c 'exit 3'");
    }

    @Test
    public void shellCommandWithoutTimeoutRunsInShell() {
        givenCommand("exit 3", true, -1);

        whenExecutedUnprivileged();

        thenSuRuns("/bin/sh -c 'exit 3'");
    }

    @Test
    public void zeroTimeoutDoesNotAddTimeoutCommand() {
        givenCommand("ls -l", false, 0);

        whenExecutedUnprivileged();

        thenSuRuns("ls -l");
    }

    @Test
    public void negativeTimeoutDoesNotAddTimeoutCommand() {
        givenCommand("ls -l", false, -2);

        whenExecutedUnprivileged();

        thenSuRuns("ls -l");
    }

    @Test
    public void shellCommandChainIsEntirelyCoveredByTimeout() {
        givenCommand("sleep 1 ; sleep 30", true, 5);

        whenExecutedUnprivileged();

        thenSuRuns("timeout -s SIGTERM 5 /bin/sh -c 'sleep 1 ; sleep 30'");
    }

    @Test
    public void singleQuotesInShellCommandAreEscaped() {
        givenCommand("echo 'a b'", true, 5);

        whenExecutedUnprivileged();

        thenSuRuns("timeout -s SIGTERM 5 /bin/sh -c 'echo '\\''a b'\\'''");
    }

    @Test
    public void environmentIsPassedBeforeTimeout() {
        givenCommand("exit 3", true, 5);
        givenEnvironmentVariable("ENV1", "VALUE1");

        whenExecutedUnprivileged();

        thenSuRuns("ENV1=VALUE1 timeout -s SIGTERM 5 /bin/sh -c 'exit 3'");
    }

